        catch (IOException ex) { Log.Write($"Could not remove temporary thumbnail files: {ex.Message}"); }
        catch (UnauthorizedAccessException ex) { Log.Write($"Could not remove temporary thumbnail files: {ex.Message}"); }
    }
}

